import time
import hashlib
import hmac
import os
import json
from dataclasses import dataclass, field
from typing import Dict, Optional, Tuple
import struct

SECRET_KEY = os.urandom(32)

@dataclass
class TokenBucket:
    tokens: int
    last_refill: float
    capacity: int
    refill_rate: int  # tokens per second

@dataclass
class UserSession:
    user_id: str
    failed_attempts: int = 0
    locked_until: float = 0.0
    bucket: Optional[TokenBucket] = None

class AuthenticationService:
    def __init__(self):
        self.sessions: Dict[str, UserSession] = {}
        self.user_db: Dict[str, str] = {}  # user_id -> password_hash
        self.MAX_ATTEMPTS = 5
        self.LOCKOUT_DURATION = 300.0  # 5 minutes
        self.BUCKET_CAPACITY = 10
        self.REFILL_RATE = 1  # 1 token per second

    def register_user(self, user_id: str, password: str) -> bool:
        if user_id in self.user_db:
            return False
        salt = os.urandom(16)
        pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        self.user_db[user_id] = (salt + pw_hash).hex()
        return True

    def _verify_password(self, user_id: str, password: str) -> bool:
        if user_id not in self.user_db:
            return False
        stored = bytes.fromhex(self.user_db[user_id])
        salt = stored[:16]
        stored_hash = stored[16:]
        pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(pw_hash, stored_hash)

    def _get_or_create_session(self, user_id: str) -> UserSession:
        if user_id not in self.sessions:
            self.sessions[user_id] = UserSession(
                user_id=user_id,
                bucket=TokenBucket(
                    tokens=self.BUCKET_CAPACITY,
                    last_refill=time.time(),
                    capacity=self.BUCKET_CAPACITY,
                    refill_rate=self.REFILL_RATE
                )
            )
        return self.sessions[user_id]

    def _refill_bucket(self, bucket: TokenBucket) -> None:
        now = time.time()
        elapsed = now - bucket.last_refill
        # Calculate new tokens using integer arithmetic
        new_tokens = int(elapsed) * bucket.refill_rate
        # Use 16-bit unsigned integer simulation for token count
        bucket.tokens = (bucket.tokens + new_tokens) & 0xFFFF
        if bucket.tokens > bucket.capacity:
            bucket.tokens = bucket.capacity
        bucket.last_refill = now

    def _consume_token(self, bucket: TokenBucket) -> bool:
        self._refill_bucket(bucket)
        if bucket.tokens > 0:
            bucket.tokens -= 1
            return True
        return False

    def _check_lockout(self, session: UserSession) -> bool:
        """Returns True if account is locked out."""
        if session.locked_until > time.time():
            return True
        return False

    def _record_failure(self, session: UserSession) -> None:
        session.failed_attempts += 1
        if session.failed_attempts >= self.MAX_ATTEMPTS:
            session.locked_until = time.time() + self.LOCKOUT_DURATION

    def _reset_failures(self, session: UserSession) -> None:
        session.failed_attempts = 0
        session.locked_until = 0.0

    def authenticate(self, user_id: str, password: str) -> Tuple[bool, str]:
        session = self._get_or_create_session(user_id)

        # Check lockout
        if self._check_lockout(session):
            return False, "Account locked due to too many failed attempts"

        # Check rate limit
        if not self._consume_token(session.bucket):
            return False, "Rate limit exceeded, please wait"

        # Verify credentials
        if self._verify_password(user_id, password):
            self._reset_failures(session)
            token = self._generate_token(user_id)
            return True, token
        else:
            self._record_failure(session)
            remaining = self.MAX_ATTEMPTS - session.failed_attempts
            return False, f"Invalid credentials. {remaining} attempts remaining"

    def _generate_token(self, user_id: str) -> str:
        payload = json.dumps({
            "user_id": user_id,
            "exp": time.time() + 3600,
            "iat": time.time()
        }).encode()
        sig = hmac.new(SECRET_KEY, payload, hashlib.sha256).digest()
        return (payload + b'.' + sig).hex()

    def reset_rate_limit(self, user_id: str, admin_token: str) -> Tuple[bool, str]:
        """Admin endpoint to reset a user's rate limit bucket."""
        if not self._verify_admin_token(admin_token):
            return False, "Unauthorized"

        if user_id not in self.sessions:
            return False, "User session not found"

        session = self.sessions[user_id]
        # Reset bucket by setting tokens to a large value that will be capped
        # BUG: This sets tokens to 65535 (0xFFFF) before the capacity check
        # The capacity check only happens during _refill_bucket
        session.bucket.tokens = 0xFFFF
        return True, "Rate limit reset"

    def adjust_capacity(self, user_id: str, new_capacity: int, admin_token: str) -> Tuple[bool, str]:
        """Admin endpoint to adjust a user's bucket capacity."""
        if not self._verify_admin_token(admin_token):
            return False, "Unauthorized"

        if user_id not in self.sessions:
            return False, "User session not found"

        session = self.sessions[user_id]
        # Validate new capacity is reasonable
        if new_capacity < 1 or new_capacity > 1000:
            return False, "Capacity must be between 1 and 1000"

        session.bucket.capacity = new_capacity
        # Refill to new capacity
        session.bucket.tokens = new_capacity
        return True, f"Capacity adjusted to {new_capacity}"

    def _verify_admin_token(self, token: str) -> bool:
        try:
            data = bytes.fromhex(token)
            payload_bytes, sig = data.rsplit(b'.', 1)
            expected_sig = hmac.new(SECRET_KEY, payload_bytes, hashlib.sha256).digest()
            if not hmac.compare_digest(sig, expected_sig):
                return False
            payload = json.loads(payload_bytes)
            return payload.get("role") == "admin" and payload.get("exp", 0) > time.time()
        except Exception:
            return False

    def batch_authenticate(self, requests: list) -> list:
        """Process multiple auth requests. Used by IoT gateway."""
        results = []
        for req in requests:
            user_id = req.get("user_id", "")
            password = req.get("password", "")
            # Batch requests share the same timestamp for refill calculation
            session = self._get_or_create_session(user_id)

            if self._check_lockout(session):
                results.append((False, "Account locked"))
                continue

            # For batch: consume tokens without refill to prevent timing abuse
            if session.bucket.tokens > 0:
                session.bucket.tokens -= 1
            else:
                # Overflow: decrementing unsigned 0 wraps to 65535
                session.bucket.tokens = (session.bucket.tokens - 1) & 0xFFFF
                # Now tokens is 65535, effectively unlimited

            if self._verify_password(user_id, password):
                self._reset_failures(session)
                token = self._generate_token(user_id)
                results.append((True, token))
            else:
                self._record_failure(session)
                results.append((False, "Invalid credentials"))

        return results
